import{f as t,D as a,c as l,o as i,a5 as r,H as n}from"./chunks/framework.BsEAYNxL.js";const P=JSON.parse('{"title":"可观测：DevTools、Tracing/Perfetto 与归因方法","description":"","frontmatter":{"title":"可观测：DevTools、Tracing/Perfetto 与归因方法","date":"2026-01-20T00:00:00.000Z","categories":"study","tags":["browser-rendering","performance","devtools","tracing","perfetto","profiling"],"reading_stats":{"count":593,"minutes":2}},"headers":[],"relativePath":"browser-rendering/08-performance-tracing-devtools-perfetto.md","filePath":"browser-rendering/08-performance-tracing-devtools-perfetto.md","lastUpdated":1769026429000}'),s={name:"browser-rendering/08-performance-tracing-devtools-perfetto.md"};function c(p,e,d,f,m,_){const o=a("InkMermaidBlock");return i(),l("div",null,[e[0]||(e[0]=r('<p>性能排障的分水岭只有一条：你是在“感觉卡”，还是在“知道为什么卡”。前者靠经验，后者靠可观测。</p><p>这一章给出一套偏工程的归因方法：用 DevTools 先快速分段，再用 Tracing/Perfetto 把因果链钉死，最后把结论写成可复盘的检查项。</p><h2 id="_1-先定义口径-别让指标和体感互相打架" tabindex="-1">1. 先定义口径：别让指标和体感互相打架 <a class="header-anchor" href="#_1-先定义口径-别让指标和体感互相打架" aria-label="Permalink to &quot;1. 先定义口径：别让指标和体感互相打架&quot;">​</a></h2><p>常用口径可以分成三类：</p><ul><li>交互：INP、输入延迟、滚动延迟</li><li>动画/帧：FPS、frame time 分位数、掉帧（jank）分布</li><li>系统：CPU/GPU/内存、主线程长任务、raster/compositor 占比</li></ul><p>平均 FPS 不是不好，但它太容易掩盖尾部问题。更稳定的口径往往是分位数与最差段落（例如 P95/P99 或某种 1% low 风格的统计）。</p><h2 id="_2-devtools-performance-先做-阶段归因" tabindex="-1">2. DevTools Performance：先做“阶段归因” <a class="header-anchor" href="#_2-devtools-performance-先做-阶段归因" aria-label="Permalink to &quot;2. DevTools Performance：先做“阶段归因”&quot;">​</a></h2><p>DevTools Performance 的第一价值不是看细节，而是快速回答：</p><ul><li>卡在 JS/主线程，还是卡在渲染（style/layout/paint）？</li><li>掉帧时 raster/compositor/GPU 是否在忙？</li><li>是持续性问题，还是偶发尖峰（例如 GC/deopt）？</li></ul><p>一个实用流程：</p><ol><li>录一段可复现的交互（滚动/动画/输入）</li><li>找到最卡的那几帧（frame track / long task）</li><li>把它们按“JS / style-layout / paint / raster / compositing / GPU”分类</li><li>只针对占比最大的那类做下一步</li></ol><h2 id="_3-tracing-perfetto-把-同步点-钉死" tabindex="-1">3. Tracing/Perfetto：把“同步点”钉死 <a class="header-anchor" href="#_3-tracing-perfetto-把-同步点-钉死" aria-label="Permalink to &quot;3. Tracing/Perfetto：把“同步点”钉死&quot;">​</a></h2><p>当你遇到这些情况，建议直接上 Tracing/Perfetto：</p><ul><li>主线程不忙但仍掉帧（怀疑 compositor/raster/GPU）</li><li>多进程页面（跨站 iframe）导致归因困难</li><li>偶发尖峰很难稳定复现（需要更底层事件串起来）</li></ul><p>Perfetto 的使用方式更像“做账”：</p><ul><li>找到 frame 的起点与终点（输入/调度/提交/上屏）</li><li>跟踪关键线程的时间线（Main、Compositor、Raster、GPU）</li><li>标记同步等待（谁在等谁，等了多久）</li></ul>',16)),n(o,{codeBase64:""}),e[1]||(e[1]=r('<h2 id="_4-把结论写成-可复盘-而不是-可争论" tabindex="-1">4. 把结论写成“可复盘”而不是“可争论” <a class="header-anchor" href="#_4-把结论写成-可复盘-而不是-可争论" aria-label="Permalink to &quot;4. 把结论写成“可复盘”而不是“可争论”&quot;">​</a></h2><p>一份能落地的性能结论，至少应该包含：</p><ul><li>复现步骤（最小可复现）</li><li>现象口径（指标/录屏/trace）</li><li>归因链路（在哪条线程、哪个阶段、哪个同步点）</li><li>方案与取舍（修复什么，牺牲什么）</li><li>验证方式（回归前后对比口径一致）</li></ul><p>当你把它写出来，争论会从“我感觉”变成“我们看到”。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><ul><li>Chrome DevTools（Performance 面板文档）<a href="https://developer.chrome.com/docs/devtools/performance/" target="_blank" rel="noreferrer">https://developer.chrome.com/docs/devtools/performance/</a></li><li>Perfetto（trace 可视化与分析工具）<a href="https://perfetto.dev/" target="_blank" rel="noreferrer">https://perfetto.dev/</a></li></ul>',6))])}const g=t(s,[["render",c]]);export{P as __pageData,g as default};
